-- Phase 3: POS, Purchases, Khata tables for a TENANT database.
-- Apply to each tenant DB (tenant_000001, ...), NOT to master_control.
-- New and older tenants also auto-create these tables on first use via
-- the store's ensurePhase3Tables, so this file is the deploy record, not
-- a one-time manual step. Additive only: CREATE TABLE IF NOT EXISTS.
CREATE TABLE IF NOT EXISTS parties (id VARCHAR(96) PRIMARY KEY, type VARCHAR(20) NOT NULL, name VARCHAR(220) NOT NULL, phone VARCHAR(40) NULL, address VARCHAR(400) NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_party_type (type)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sales (id VARCHAR(96) PRIMARY KEY, invoice_no VARCHAR(64) NOT NULL UNIQUE, branch_id VARCHAR(96) NOT NULL, customer_id VARCHAR(96) NULL, user_id VARCHAR(96) NOT NULL, subtotal DECIMAL(14,2) NOT NULL, discount DECIMAL(14,2) NOT NULL DEFAULT 0, total DECIMAL(14,2) NOT NULL, paid_amount DECIMAL(14,2) NOT NULL DEFAULT 0, balance_due DECIMAL(14,2) NOT NULL DEFAULT 0, payment_type VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'completed', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_sale_branch_time (branch_id, created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sale_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sale_id VARCHAR(96) NOT NULL, medicine_id VARCHAR(96) NOT NULL, batch_id VARCHAR(96) NOT NULL, batch_no VARCHAR(96) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(14,2) NOT NULL, returned_quantity INT NOT NULL DEFAULT 0, INDEX idx_sale_item_sale (sale_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS purchases (id VARCHAR(96) PRIMARY KEY, branch_id VARCHAR(96) NOT NULL, supplier_id VARCHAR(96) NOT NULL, user_id VARCHAR(96) NOT NULL, subtotal DECIMAL(14,2) NOT NULL, paid_amount DECIMAL(14,2) NOT NULL DEFAULT 0, balance_due DECIMAL(14,2) NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'pending', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_purchase_branch_time (branch_id, created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS purchase_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, purchase_id VARCHAR(96) NOT NULL, medicine_id VARCHAR(96) NOT NULL, batch_id VARCHAR(96) NOT NULL, batch_no VARCHAR(96) NOT NULL, expiry_date DATE NOT NULL, quantity INT NOT NULL, purchase_price DECIMAL(14,2) NOT NULL, sale_price DECIMAL(14,2) NOT NULL, INDEX idx_purchase_item_purchase (purchase_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS khata_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, party_id VARCHAR(96) NOT NULL, entry_type VARCHAR(40) NOT NULL, debit DECIMAL(14,2) NOT NULL DEFAULT 0, credit DECIMAL(14,2) NOT NULL DEFAULT 0, reference_id VARCHAR(96) NULL, note VARCHAR(400) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_khata_party (party_id)) ENGINE=InnoDB;
